// Shared bits of the cutover driver: logging, the result registry and the
// run context (environment, artifact paths, evidence directory).
//
// Every check ends in exactly one of four states, and only `pass` is success:
//   pass         observed on a real core process
//   fail         observed and wrong
//   unverified   not generated by the old build, or the new build does not
//                offer the surface yet: NEVER counted as success
//   todo         the check needs a new-build surface that is not implemented
//                (named in the detail); also never counted as success
import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";

export class Results {
  constructor(file) {
    this.file = file;
    this.items = [];
  }

  add(id, status, detail = "") {
    if (!["pass", "fail", "unverified", "todo"].includes(status)) throw new Error(`bad status ${status}`);
    const item = { id, status, detail: typeof detail === "string" ? detail : JSON.stringify(detail) };
    this.items.push(item);
    log(`${status.toUpperCase().padEnd(10)} ${id}${item.detail ? ` — ${item.detail}` : ""}`);
    this.flush();
    return item;
  }

  pass(id, detail) {
    return this.add(id, "pass", detail);
  }

  fail(id, detail) {
    return this.add(id, "fail", detail);
  }

  unverified(id, detail) {
    return this.add(id, "unverified", detail);
  }

  todo(id, detail) {
    return this.add(id, "todo", detail);
  }

  /** Records pass/fail from a boolean. */
  check(id, ok, detail) {
    return this.add(id, ok ? "pass" : "fail", detail);
  }

  get failed() {
    return this.items.filter((i) => i.status === "fail");
  }

  summary() {
    const count = (s) => this.items.filter((i) => i.status === s).length;
    return { pass: count("pass"), fail: count("fail"), unverified: count("unverified"), todo: count("todo") };
  }

  flush() {
    if (this.file) fs.writeFileSync(this.file, JSON.stringify({ summary: this.summary(), items: this.items }, null, 2));
  }
}

let logFile = null;
export function setLogFile(file) {
  logFile = file;
}

export function log(message) {
  const line = `${new Date().toISOString()} ${message}`;
  process.stderr.write(`${line}\n`);
  if (logFile) fs.appendFileSync(logFile, `${line}\n`);
}

/** Directory the driver keeps its own files in, inside the work root (never the state root). */
export function driverDir(root) {
  const dir = path.join(root, "driver");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

export function readJson(file) {
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

export function writeJson(file, value) {
  fs.writeFileSync(file, JSON.stringify(value, null, 2));
}

/** A valid 1x1 RGBA PNG, built here (never a hand-typed blob): the smallest image attachment. */
export function png1x1() {
  const chunk = (type, data) => {
    const body = Buffer.concat([Buffer.from(type, "ascii"), data]);
    const out = Buffer.alloc(12 + data.length);
    out.writeUInt32BE(data.length, 0);
    body.copy(out, 4);
    out.writeUInt32BE(zlib.crc32(body), 8 + data.length);
    return out;
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(1, 0);
  ihdr.writeUInt32BE(1, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 6; // RGBA
  const raw = Buffer.from([0, 0x20, 0x40, 0x60, 0xff]); // filter byte + one pixel
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk("IHDR", ihdr),
    chunk("IDAT", zlib.deflateSync(raw)),
    chunk("IEND", Buffer.alloc(0)),
  ]);
}
